+    Label label = Label.parseCanonicalUnchecked("//foo:bar");
+    Label shorthandLabel = Label.parseCanonicalUnchecked("//foo");
+    Label ultraShorthandLabel = Label.parseCanonicalUnchecked("//:my_main");
+    Object list =
